create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  email text,
  role text not null default 'user' check (role in ('user', 'admin')),
  is_premium boolean not null default false,
  created_at timestamptz not null default now()
);
create table public.tests (id bigint generated by default as identity primary key, title text not null, description text, level text not null default 'N5', duration_minutes integer not null, is_premium boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.questions (id bigint generated by default as identity primary key, test_id bigint references public.tests(id) on delete cascade, section text not null check (section in ('Vocabulary','Grammar','Reading','Listening')), question_number integer, question_text text, question_type text not null default 'multiple_choice', image_url text, audio_url text, explanation text, points integer not null default 1, created_at timestamptz not null default now());
create table public.choices (id bigint generated by default as identity primary key, question_id bigint references public.questions(id) on delete cascade, choice_key text not null, choice_text text not null, is_correct boolean not null default false);
create table public.attempts (id bigint generated by default as identity primary key, user_id uuid references auth.users(id), test_id bigint references public.tests(id), score integer not null default 0, total_points integer not null default 0, percentage numeric, status text not null default 'in_progress', started_at timestamptz not null default now(), completed_at timestamptz);
create table public.user_answers (id bigint generated by default as identity primary key, attempt_id bigint references public.attempts(id) on delete cascade, question_id bigint references public.questions(id), choice_id bigint references public.choices(id), is_correct boolean, created_at timestamptz not null default now());
create table public.payments (id bigint generated by default as identity primary key, user_id uuid references auth.users(id), amount integer not null, payment_method text not null check (payment_method in ('KPay','WavePay')), transaction_id text not null, screenshot_url text, status text not null default 'pending' check (status in ('pending','approved','rejected')), admin_note text, created_at timestamptz not null default now(), approved_at timestamptz);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name, email) values (new.id, new.raw_user_meta_data->>'full_name', new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin'); $$;

alter table public.profiles enable row level security; alter table public.tests enable row level security; alter table public.questions enable row level security; alter table public.choices enable row level security; alter table public.attempts enable row level security; alter table public.user_answers enable row level security; alter table public.payments enable row level security;
create policy "own profile read" on public.profiles for select using (id = auth.uid() or public.is_admin()); create policy "own profile update" on public.profiles for update using (id = auth.uid() or public.is_admin());
create policy "active tests read" on public.tests for select using ((is_active and auth.uid() is not null) or public.is_admin()); create policy "admin tests" on public.tests for all using (public.is_admin());
create policy "questions read" on public.questions for select using (auth.uid() is not null); create policy "admin questions" on public.questions for all using (public.is_admin()); create policy "choices read" on public.choices for select using (auth.uid() is not null); create policy "admin choices" on public.choices for all using (public.is_admin());
create policy "own attempts" on public.attempts for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin()); create policy "own answers" on public.user_answers for all using (exists (select 1 from public.attempts a where a.id = attempt_id and (a.user_id = auth.uid() or public.is_admin()))) with check (exists (select 1 from public.attempts a where a.id = attempt_id and (a.user_id = auth.uid() or public.is_admin())));
create policy "own payments" on public.payments for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin());